def isValid(word: str) -> bool:
    if len(word) < 3:
        return False

    vowels = set('aeiouAEIOU')
    has_vowel = False
    has_consonant = False

    for char in word:
        if char.isdigit():
            continue
        elif char.isalpha():
            if char in vowels:
                has_vowel = True
            else:
                has_consonant = True
        else:
            # Contains invalid character like '@', '#', '$'
            return False

    return has_vowel and has_consonant
