def maximumTime(s: str) -> str:
    # Convert to list for mutability
    chars = list(s)

    # Handle hours tens digit (index 0)
    if chars[0] == '?':
        # If units digit is '?' or <= '1', then tens can be '1'
        # If units digit is > '1', then tens must be '0' because max hour is 11
        if chars[1] == '?' or chars[1] <= '1':
            chars[0] = '1'
        else:
            chars[0] = '0'

    # Handle hours units digit (index 1)
    if chars[1] == '?':
        # If tens digit is '1', units can be at most '1' (so max is 11)
        # If tens digit is '0', units can be up to '9' (so max is 09)
        if chars[0] == '1':
            chars[1] = '1'
        else:
            chars[1] = '9'

    # Handle minutes tens digit (index 3)
    if chars[3] == '?':
        # Minutes tens digit can be at most '5'
        chars[3] = '5'

    # Handle minutes units digit (index 4)
    if chars[4] == '?':
        # Minutes units digit can be at most '9'
        chars[4] = '9'

    return "".join(chars)
```

