def findRectangleWithLongestDiagonal(dimensions: list[list[int]]) -> int:
    max_area = -1
    max_diagonal_sq = -1

    for dim in dimensions:
        length, width = dim[0], dim[1]
        diagonal_sq = length * length + width * width
        area = length * width

        if diagonal_sq > max_diagonal_sq:
            max_diagonal_sq = diagonal_sq
            max_area = area
        elif diagonal_sq == max_diagonal_sq:
            if area > max_area:
                max_area = area

    return max_area
