import sys

def solve():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    N = int(input_data[0])
    M = int(input_data[1])
    S = input_data[2:]

    # Check if we have enough rows and columns
    if N < 9 or M < 9:
        return

    results = []

    # Iterate over all possible top-left positions (i, j) for a 9x9 region
    # i ranges from 0 to N-9, j ranges from 0 to M-9
    for i in range(N - 8):
        for j in range(M - 8):
            valid = True

            # Condition 1: Top-left 3x3 region (rows i..i+2, cols j..j+2) must be all black (#)
            for r in range(3):
                for c in range(3):
                    if S[i + r][j + c] != '#':
                        valid = False
                        break
                if not valid:
                    break
            if not valid:
                continue

            # Condition 2: Bottom-right 3x3 region (rows i+6..i+8, cols j+6..j+8) must be all black (#)
            for r in range(3):
                for c in range(3):
                    if S[i + 6 + r][j + 6 + c] != '#':
                        valid = False
                        break
                if not valid:
                    break
            if not valid:
                continue

            # Condition 3: 7 cells adjacent to top-left 3x3 within the 9x9 region must be white (.)
            # Cells: (i, j+3), (i+1, j+3), (i+2, j+3)
            #        (i+3, j), (i+3, j+1), (i+3, j+2)
            #        (i+3, j+3)
            adj_tl = [
                (i, j+3), (i+1, j+3), (i+2, j+3),
                (i+3, j), (i+3, j+1), (i+3, j+2),
                (i+3, j+3)
            ]
            for r, c in adj_tl:
                if S[r][c] != '.':
                    valid = False
                    break
            if not valid:
                continue

            # Condition 4: 7 cells adjacent to bottom-right 3x3 within the 9x9 region must be white (.)
            # Cells: (i+5, j+6), (i+5, j+7), (i+5, j+8)
            #        (i+6, j+5), (i+7, j+5), (i+8, j+5)
            #        (i+5, j+5)
            adj_br = [
                (i+5, j+6), (i+5, j+7), (i+5, j+8),
                (i+6, j+5), (i+7, j+5), (i+8, j+5),
                (i+5, j+5)
            ]
            for r, c in adj_br:
                if S[r][c] != '.':
                    valid = False
                    break
            if not valid:
                continue

            # If all conditions met, store result (1-indexed)
            results.append((i + 1, j + 1))

    # Output results sorted lexicographically (which they already are due to iteration order)
    for r, c in results:
        print(f"{r} {c}")

