def findPrimePairs(n: int) -> list:
    def is_prime(num: int) -> bool:
        if num < 2:
            return False
        if num == 2:
            return True
        if num % 2 == 0:
            return False
        i = 3
        while i * i <= num:
            if num % i == 0:
                return False
            i += 2
        return True

    result = []
    for x in range(2, n // 2 + 1):
        y = n - x
        if x > y:
            break
        if is_prime(x) and is_prime(y):
            result.append([x, y])

    return result
```

