        # Find third character of T in S after idx2
        idx3 = -1
        for i in range(idx2 + 1, len(s)):
            if s[i].upper() == t[2]:
                idx3 = i
                break

        return idx3 != -1

    # Method 2: Take a subsequence of length 2 from S, convert to uppercase, append 'X' to form T
    # So T must end with 'X', and the first two characters of T must be found as a subsequence in S
    def find_subsequence_2_with_x(s, t):
