import sys

def solve():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    iterator = iter(input_data)

    try:
        N = int(next(iterator))
        M = int(next(iterator))
        L = []
        for _ in range(N):
            L.append(int(next(iterator)))
    except StopIteration:
        return

    # Binary search for the minimum width W
    # Lower bound for W: max(L_i) because a single word must fit on a line
    # Upper bound for W: sum(L_i) + (N - 1) because all words can fit on one line

    low = max(L)
    high = sum(L) + N - 1

    def check(W, num_lines_limit):
        """Check if it's possible to fit the words into num_lines_limit lines with window width W."""
        lines = 1
        current_width = 0

        for length in L:
            if current_width == 0:
                # Start of a new line
                if length > W:
                    return False
                current_width = length
            else:
                # Try to add a space and the next word
                if current_width + 1 + length <= W:
                    current_width += 1 + length
                else:
                    lines += 1
                    if lines > num_lines_limit:
                        return False
                    current_width = length
                    if current_width > W:
                        return False
        return True

    ans = high

    while low <= high:
        mid = (low + high) // 2
        if check(mid, M):
            ans = mid
            high = mid - 1
        else:
            low = mid + 1

    print(ans)

solve()
```

