    # Helper function to check if a list is strictly increasing
    def is_strictly_increasing(arr):
        for i in range(1, len(arr)):
            if arr[i] <= arr[i-1]:
                return False
        return True

    count = 0

    # Iterate over all possible subarrays [i, j]
    for i in range(n):
        for j in range(i, n):
            # Form the remaining array by removing nums[i:j+1]
            remaining = nums[:i] + nums[j+1:]

            # Check if the remaining array is strictly increasing
            if is_strictly_increasing(remaining):
                count += 1

