class Solution:
    def maxSum(self, nums: List[int], k: int) -> int:
        MOD = 10**9 + 7

        # Count the number of set bits at each position across all numbers
        bit_count = [0] * 30

        for num in nums:
            for i in range(30):
                if (num >> i) & 1:
                    bit_count[i] += 1

        # Construct the k largest possible numbers based on bit counts
        # We want to maximize the sum of squares, so we should greedily form the largest numbers
        # For each of the k positions, construct a number by setting bit i if bit_count[i] > 0
        # Then decrement bit_count[i]

        result_nums = []
        for _ in range(k):
            val = 0
            for i in range(30):
                if bit_count[i] > 0:
                    val |= (1 << i)
                    bit_count[i] -= 1
            result_nums.append(val)

        # Calculate sum of squares modulo MOD
        total = 0
        for num in result_nums:
            total = (total + (num * num) % MOD) % MOD

        return total
