def solve(nums: list[int], moveFrom: list[int], moveTo: list[int]) -> list[int]:
    # Use a set to track occupied positions for efficient lookups and updates
    occupied = set(nums)

    for src, dst in zip(moveFrom, moveTo):
        # If the source position is occupied, remove it and add the destination
        if src in occupied:
            occupied.remove(src)
            occupied.add(dst)

    # Return the sorted list of occupied positions
