def max_palindromes(words):
    n = len(words)
    from collections import defaultdict
    total_chars = sum(len(word) for word in words)
    freq = defaultdict(int)
    for word in words:
        for char in word:
            freq[char] += 1

    total_odd = 0
    for char in freq:
        if freq[char] % 2 != 0:
            total_odd += 1

    k = total_chars // 2
    if total_odd > 0:
        k += 1
