def findOccurrences(nums: list[int], queries: list[int], x: int) -> list[int]:
    # Precompute indices where x occurs in nums
    indices = []
    for i, num in enumerate(nums):
        if num == x:
            indices.append(i)

    # For each query, get the k-th occurrence (k = queries[i])
    # Since indices is 0-based, the k-th occurrence is at indices[k-1]
    # If k-1 >= len(indices), return -1

    answer = []
    for q in queries:
        if q - 1 < len(indices):
            answer.append(indices[q - 1])
        else:
            answer.append(-1)

    return answer
