class Solution:
    def specialPerm(self, nums: List[int]) -> int:
        MOD = 10**9 + 7
        n = len(nums)

        # Precompute adjacency: can we place b after a?
        # i.e., is nums[i] divisible by nums[j] or vice versa?
        adj = [[False] * n for _ in range(n)]
        for i in range(n):
            for j in range(n):
                if i != j:
                    if nums[i] % nums[j] == 0 or nums[j] % nums[i] == 0:
                        adj[i][j] = True

        # DP with bitmask
        # dp[mask][last] = number of ways to arrange elements represented by mask, ending with element 'last'
        full_mask = (1 << n) - 1
        dp = [[0] * n for _ in range(1 << n)]

        # Base case: single elements
        for i in range(n):
            dp[1 << i][i] = 1

        # Iterate over masks
        for mask in range(1, 1 << n):
            for last in range(n):
                if not (mask & (1 << last)):
                    continue
                if dp[mask][last] == 0:
                    continue

                # Try to add a new element 'next'
                for nxt in range(n):
                    if mask & (1 << nxt):
                        continue
                    if adj[last][nxt]:
                        new_mask = mask | (1 << nxt)
                        dp[new_mask][nxt] = (dp[new_mask][nxt] + dp[mask][last]) % MOD

        # Sum up all dp[full_mask][i] for all i
        result = 0
        for i in range(n):
            result = (result + dp[full_mask][i]) % MOD

        return result
