def findValueOfPartition(nums: list[int]) -> int:
    nums.sort()
    min_diff = float('inf')
    for i in range(1, len(nums)):
        diff = nums[i] - nums[i - 1]
        if diff < min_diff:
            min_diff = diff
    return min_diff
```

```python
def findDuplicateXOR(nums: list[int]) -> int:
    count = {}
    for num in nums:
        count[num] = count.get(num, 0) + 1

    result = 0
    for num, freq in count.items():
        if freq == 2:
            result ^= num

    return result
```

```python
def max_jumps(nums: list[int], target: int) -> int:
    n = len(nums)
    # dp[i] represents the maximum number of jumps to reach index i from index 0
    # Initialize with -infinity to represent unreachable, except dp[0] = 0
    dp = [-float('inf')] * n
    dp[0] = 0

    for i in range(n):
        if dp[i] == -float('inf'):
            continue
        for j in range(i + 1, n):
            diff = nums[j] - nums[i]
            if -target <= diff <= target:
                if dp[j] < dp[i] + 1:
                    dp[j] = dp[i] + 1

    return dp[n - 1] if dp[n - 1] != -float('inf') else -1
```

