def min_time_to_revert(word: str, k: int) -> int:
    n = len(word)
    pattern_changes = [(word[i:i+k], word[n-k:n+k-i]) for i in range(n-k+1)]
    dp = [False] * (n+1)
    dp[0] = True

    for i in range(n-k+1):
        new_dp = dp.copy()
        for j in range(n+1):
            if dp[j]:
                new_dp[j+k] = True
                new_dp[(j+k) % n] = True
        dp = new_dp

    for i in range(1, n+1):
        if dp[i]:
            return i

    return -1  # This should never be reached given the constraints
