def count_sub_multisets(nums, l, r):
    zeros_count = 0
    non_zero_nums = []
    for x in nums:
        if x == 0:
            zeros_count += 1
        else:
            non_zero_nums.append(x)

    if not non_zero_nums and zeros_count == 0:
        # Only zeros, then the answer is zeros_count+1 if l==0, but need to check the range
        if l <= 0 <= r:
            return (zeros_count + 1) % mod
        else:
            return 0

    total_sum = sum(non_zero_nums)
    from collections import defaultdict
    freq = defaultdict(int)
    for x in non_zero_nums:
        freq[x] += 1

    dp = [0] * (total_sum + 1)
    dp[0] = 1

    for x, f in freq.items():
        new_dp = dp.copy()
        for s in range(total_sum, -1, -1):
            if s < x:
                continue
            temp_sum = 0
            k = 1
            while k <= f and s >= k * x:
                temp_sum = (temp_sum + dp[s - k * x]) % mod
                k += 1
            new_dp[s] = (new_dp[s] + temp_sum) % mod
        dp = new_dp

    factor = zeros_count + 1
    for i in range(total_sum + 1):
        dp[i] = (dp[i] * factor) % mod

    ans = 0
    for s in range(l, r + 1):
        if s <= total_sum:
            ans = (ans + dp[s]) % mod

    return ans
