def largestPerimeter(nums):
    nums.sort()
    n = len(nums)
    if n < 3:
        return -1
    prefix = [0] * n
    prefix[0] = nums[0]
    for i in range(1, n):
        prefix[i] = prefix[i-1] + nums[i]
    for i in range(n-1, 1, -1):
        if prefix[i] > 2 * nums[i]:
            return prefix[i]
    return -1
