def medianOfUniquenessArray(nums):
    n = len(nums)
    total_subarrays = n * (n + 1) // 2
    target = (total_subarrays + 1) // 2

    def count_subarrays_at_most(k):
        if k == 0:
            return 0
        count = 0
        left = 0
        freq = {}
        distinct = 0
        for right in range(n):
            val = nums[right]
            freq[val] = freq.get(val, 0) + 1
            if freq[val] == 1:
                distinct += 1
            while distinct > k:
                left_val = nums[left]
                freq[left_val] -= 1
                if freq[left_val] == 0:
                    distinct -= 1
                left += 1
            count += right - left + 1
        return count

    lo, hi = 1, n
    while lo < hi:
        mid = (lo + hi) // 2
        if count_subarrays_at_most(mid) >= target:
            hi = mid
        else:
            lo = mid + 1

    return lo
```

