def permutation_difference(s: str, t: str) -> int:
    # Build a position map for string t
    t_positions = {char: idx for idx, char in enumerate(t)}

    # Calculate the permutation difference
    total_diff = 0
    for idx, char in enumerate(s):
        total_diff += abs(idx - t_positions[char])

    return total_diff
