def permutationDifference(s, t):
    # Create a dictionary to store the index of each character in s
    map_s = {}
    for i, char in enumerate(s):
        map_s[char] = i

    # Create a dictionary to store the index of each character in t
    map_t = {}
    for i, char in enumerate(t):
        map_t[char] = i

    total = 0
    # Iterate over each character in s and calculate the absolute difference in indices between s and t
    for char in map_s:
        total += abs(map_s[char] - map_t[char])

    return total

