        a, b = b, a % b
    return a

class UnionFind:
    def __init__(self, n):
        self.parent = list(range(n))
        self.rank = [0] * n
        self.count = n

    def find(self, x):
        if self.parent[x] != x:
            self.parent[x] = self.find(self.parent[x])
        return self.parent[x]

    def union(self, x, y):
        rootX = self.find(x)
        rootY = self.find(y)
        if rootX != rootY:
            if self.rank[rootX] > self.rank[rootY]:
                self.parent[rootY] = rootX
            elif self.rank[rootX] < self.rank[rootY]:
                self.parent[rootX] = rootY
            else:
                self.parent[rootY] = rootX
                self.rank[rootX] += 1
            self.count -= 1

def canTraverseAllPairs(nums):
    n = len(nums)
    if n == 1:
        return True

    # If any number is 1, and there's more than 1 element, it can't connect to anything via gcd > 1
    # because gcd(1, x) = 1 for any x.
    if 1 in nums:
        return False

    # Map each prime factor to the first index that has it
    prime_to_index = {}
    uf = UnionFind(n)

    # Precompute smallest prime factor for efficient factorization up to max(nums)
    max_val = max(nums)
    spf = list(range(max_val + 1))
    for i in range(2, int(max_val**0.5) + 1):
        if spf[i] == i:  # i is prime
            for j in range(i*i, max_val + 1, i):
                if spf[j] == j:
                    spf[j] = i

    for idx, num in enumerate(nums):
        # Factorize num using spf
        temp = num
        while temp > 1:
            p = spf[temp]
            # Union this index with any other index that has prime factor p
            if p in prime_to_index:
                uf.union(idx, prime_to_index[p])
            else:
                prime_to_index[p] = idx

            # Remove all factors of p from temp
            while temp % p == 0:
                temp //= p

    # Check if all elements are in the same component
    return uf.count == 1
