def possibleTraverse(nums):
    # Build a mapping from prime factors to the indices that contain them
    factor_to_indices = defaultdict(list)
    for index, num in enumerate(nums):
        for factor in range(2, int(num**0.5) + 1):
            if num % factor == 0:
                factor_to_indices[factor].append(index)
                while num % factor == 0:
                    num //= factor
        if num > 1:  # If there's a prime factor larger than sqrt(num)
            factor_to_indices[num].append(index)

    # Union-Find data structure to keep track of connected components
    parent = list(range(len(nums)))

    def find(x):
        if parent[x] != x:
            parent[x] = find(parent[x])
        return parent[x]

    def union(x, y):
        rootX = find(x)
        rootY = find(y)
        if rootX != rootY:
            parent[rootY] = rootX

    # Union all indices that share at least one common prime factor
    for indices in factor_to_indices.values():
        first_index = indices[0]
        for index in indices[1:]:
            union(first_index, index)

    # Check if all nodes are in the same connected component
    root = find(0)
    for index in range(1, len(nums)):
        if find(index) != root:
            return False
    return True
